-- READ-ONLY inspection: run in Supabase SQL Editor before migrations and save the results.
select table_name,column_name,ordinal_position,data_type,udt_name,is_nullable,column_default from information_schema.columns where table_schema='public' and table_name in ('profiles','offers','subscriptions','connections','messages','deals','reviews') order by table_name,ordinal_position;
select tc.table_name,tc.constraint_name,tc.constraint_type,kcu.column_name,ccu.table_name as foreign_table,ccu.column_name as foreign_column from information_schema.table_constraints tc left join information_schema.key_column_usage kcu on tc.constraint_name=kcu.constraint_name and tc.table_schema=kcu.table_schema left join information_schema.constraint_column_usage ccu on ccu.constraint_name=tc.constraint_name and ccu.table_schema=tc.table_schema where tc.table_schema='public' and tc.table_name in ('profiles','offers','subscriptions','connections','messages','deals','reviews') order by tc.table_name,tc.constraint_type,tc.constraint_name;
select schemaname,tablename,indexname,indexdef from pg_indexes where schemaname='public' and tablename in ('profiles','offers','subscriptions','connections','messages','deals','reviews') order by tablename,indexname;
select n.nspname as schema_name,c.relname as table_name,c.relrowsecurity as rls_enabled,c.relforcerowsecurity as rls_forced from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r' and c.relname in ('profiles','offers','subscriptions','connections','messages','deals','reviews') order by c.relname;
select schemaname,tablename,policyname,permissive,roles,cmd,qual,with_check from pg_policies where schemaname='public' and tablename in ('profiles','offers','subscriptions','connections','messages','deals','reviews') order by tablename,policyname;
